'use strict';
// Share cards (Open Graph, 1200×630) for the fixed public pages. Each page and language gets its own
// image so a link preview names the page it points to, instead of one shared brand picture.
// The PNGs are generated by scripts/og/generate-cards.js and committed under public/images/og/.
const fs = require('node:fs');
const path = require('node:path');

const PUBLIC_DIR = path.join(__dirname, '..', '..', 'public');

// Route path -> card key (file: public/images/og/<key>-<fa|en>.png).
const CARD_PAGES = {
  '/': 'home',
  '/tools': 'tools',
  '/shop': 'shop',
  '/articles': 'articles',
  '/library': 'library',
  '/support': 'support',
  '/about': 'about'
};

// Headline text printed on each card. Keep short; the card is a preview, not the page title.
const CARD_TEXT = {
  home: { fa: 'محاسبات تأسیسات، آموزش و مقررات گاز', en: 'Building services calculators, courses and regulations' },
  tools: { fa: 'ماشین‌حساب‌های تأسیسات', en: 'Building services calculators' },
  shop: { fa: 'دوره‌های آموزشی تأسیسات', en: 'Building services courses' },
  articles: { fa: 'مقالات تأسیسات و لوله‌کشی گاز', en: 'Building services and gas piping articles' },
  library: { fa: 'مقررات ملی ساختمان و منابع فنی', en: 'Building regulations and technical resources' },
  support: { fa: 'مرکز راهنما و پشتیبانی', en: 'Help centre and support' },
  about: { fa: 'درباره نوگیتی', en: 'About Novingity' }
};

const cardFile = (key, locale) => `/public/images/og/${key}-${locale === 'en' ? 'en' : 'fa'}.jpg`;

// Returns the web path of the card for a route and locale, or null when the route has no card.
function cardPath(routePath, locale) {
  const key = Object.prototype.hasOwnProperty.call(CARD_PAGES, routePath) ? CARD_PAGES[routePath] : null;
  return key ? cardFile(key, locale) : null;
}

// True when the generated file is on disk (so a missing card falls back to the brand picture).
function cardExists(webPath) {
  return fs.existsSync(path.join(PUBLIC_DIR, webPath.replace(/^\/public\//, '')));
}

module.exports = { CARD_PAGES, CARD_TEXT, cardPath, cardExists, cardFile };
